import frappe
from frappe import _

def execute(filters=None):
    columns = [
        {"label": _("Airline"), "fieldname": "airline", "fieldtype": "Link", "options": "Airline"},
        {"label": _("Revenue"), "fieldname": "revenue", "fieldtype": "Currency"},
    ]

    data = frappe.db.get_all(
        "Airplane Ticket",
        fields=["airline", "sum(price) as revenue"],
        group_by="airline",
        order_by="revenue desc"
    )

    total_revenue = sum(d.revenue for d in data if d.revenue)
    chart = {
        "data": {
            "labels": [d["airline"] for d in data],
            "datasets": [{"values": [d["revenue"] for d in data]}]
        },
        "type": "donut"
    }

    return columns, data, None, chart, {"revenue": total_revenue}
